import * as THREE from 'three';
export const FRAME_HEIGHT=4.7, FRAME_WIDTH=4.7*600/720;
export function polygonBounds(points){return {minX:Math.min(...points.map(p=>p[0])),maxX:Math.max(...points.map(p=>p[0])),minY:Math.min(...points.map(p=>p[1])),maxY:Math.max(...points.map(p=>p[1]))};}
export function validatePolygon(points){if(!Array.isArray(points)||points.length<3||points.length>256||points.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)||v<0||v>1)))throw Error('윤곽은 화면 안에서 3개 이상의 점으로 지정해 주세요.');const b=polygonBounds(points);if(b.maxX-b.minX<.005||b.maxY-b.minY<.005)throw Error('부위 윤곽이 너무 작습니다.');return b;}
export function spanAt(points,y){const hits=[];for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];if((a[1]<=y&&b[1]>y)||(b[1]<=y&&a[1]>y))hits.push(a[0]+(y-a[1])*(b[0]-a[0])/(b[1]-a[1]));}hits.sort((a,b)=>a-b);if(hits.length<2)return null;if(hits.length>2)throw Error('가로로 갈라지는 윤곽은 두 부위로 나누어 지정해 주세요.');return [hits[0],hits[hits.length-1]];}
export function loftFromContours(front,side){const f=validatePolygon(front),s=validatePolygon(side),rows=48,sides=48,vertices=[],indices=[];const topCenter=[],bottomCenter=[];
for(let r=0;r<=rows;r++){const t=.001+.998*r/rows;const fy=f.minY+t*(f.maxY-f.minY),sy=s.minY+t*(s.maxY-s.minY);const fs=spanAt(front,fy),ss=spanAt(side,sy);if(!fs||!ss)throw Error('윤곽을 겹치지 않는 닫힌 선으로 다시 지정해 주세요.');const cx=((fs[0]+fs[1])/2-.5)*FRAME_WIDTH,cz=(.5-(ss[0]+ss[1])/2)*FRAME_WIDTH,rx=(fs[1]-fs[0])/2*FRAME_WIDTH,rz=(ss[1]-ss[0])/2*FRAME_WIDTH,y=(1-fy)*FRAME_HEIGHT;for(let j=0;j<sides;j++){const a=2*Math.PI*j/sides;vertices.push(cx+rx*Math.cos(a),y,cz+rz*Math.sin(a));}if(r===0)topCenter.push(cx,y,cz);if(r===rows)bottomCenter.push(cx,y,cz);}
for(let r=0;r<rows;r++)for(let j=0;j<sides;j++){const a=r*sides+j,b=r*sides+(j+1)%sides,c=(r+1)*sides+j,d=(r+1)*sides+(j+1)%sides;indices.push(a,b,c,b,d,c);}
const ti=vertices.length/3;vertices.push(...topCenter,...bottomCenter);for(let j=0;j<sides;j++){indices.push(ti,(j+1)%sides,j);indices.push(ti+1,rows*sides+j,rows*sides+(j+1)%sides);}
const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));geometry.setIndex(indices);geometry.computeVertexNormals();geometry.computeBoundingBox();const center=geometry.boundingBox.getCenter(new THREE.Vector3());geometry.translate(-center.x,-center.y,-center.z);geometry.computeBoundingBox();return {geometry,position:center.toArray()};}
export function detailGeometry(shape){if(shape==='cone')return new THREE.ConeGeometry(.5,1,48);if(shape==='ring')return new THREE.TorusGeometry(.38,.12,16,64);if(shape==='box')return new THREE.BoxGeometry(1,1,1,2,2,2);return new THREE.SphereGeometry(.5,40,28);}
export function validPart(raw){if(!raw||typeof raw!=='object')throw Error('부위 데이터가 올바르지 않습니다.');const p={id:String(raw.id||'').slice(0,30),name:String(raw.name||'부위').slice(0,60),color:/^#[a-f0-9]{6}$/i.test(raw.color)?raw.color:'#bc8051',type:['contour','extruded'].includes(raw.type)?raw.type:'primitive',shape:['ball','patch','cone','ring','box'].includes(raw.shape)?raw.shape:'ball',contours:{},visible:raw.visible!==false};if(!/^[a-zA-Z0-9_-]{1,30}$/.test(p.id))throw Error('부위 번호가 올바르지 않습니다.');for(const v of ['front','side','back'])if(raw.contours?.[v]?.length){validatePolygon(raw.contours[v]);p.contours[v]=raw.contours[v].map(a=>[...a]);}for(const [k,def,min,max]of [['position',[0,2.35,0],-1000000,1000000],['rotation',[0,0,0],-100,100],['scale',[1,1,1],.000001,100000]])p[k]=Array.isArray(raw[k])&&raw[k].length===3&&raw[k].every(v=>Number.isFinite(v)&&v>=min&&v<=max)?[...raw[k]]:def;if(p.type==='contour'&&(!p.contours.front||!p.contours.side))throw Error('윤곽 부위에는 정면과 측면이 필요합니다.');if(p.type==='extruded'){if(!p.contours.front)throw Error('추가 부위의 정면 윤곽이 필요합니다.');p.depth=Number.isFinite(raw.depth)&&raw.depth>=.005&&raw.depth<=20?raw.depth:.15;}if(typeof raw.groupId==='string'&&/^G[0-9]{1,16}$/.test(raw.groupId))p.groupId=raw.groupId;p.sourceScope=raw.sourceScope==='part'?'part':'doll';return p;}
export function extrudeFromContour(front,depth=.15){validatePolygon(front);if(!Number.isFinite(depth)||depth<.005||depth>20)throw Error('두께 범위를 확인해 주세요.');const shape=new THREE.Shape();front.forEach((p,i)=>{const x=(p[0]-.5)*FRAME_WIDTH,y=(1-p[1])*FRAME_HEIGHT;if(i)shape.lineTo(x,y);else shape.moveTo(x,y);});shape.closePath();const geometry=new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:false,steps:1,curveSegments:24});geometry.translate(0,0,-depth/2);geometry.computeBoundingBox();const center=geometry.boundingBox.getCenter(new THREE.Vector3());geometry.translate(-center.x,-center.y,-center.z);geometry.computeVertexNormals();geometry.computeBoundingBox();return {geometry,position:center.toArray()};}
